mockup.css:
.mock-hero-knockout-type { background: #0e0e0d; color: #f2efe8;
  font-family: "Helvetica Neue", Inter, ui-sans-serif, sans-serif;
  display: flex; flex-direction: column; justify-content: center; padding: 0 5cqw; }
.mock-hero-knockout-type .cut { font-weight: 800; font-size: 15.5cqw; line-height: .84; letter-spacing: -.045em;
  text-transform: uppercase; background-image:
    radial-gradient(70% 90% at 30% 20%, rgba(255,255,255,.4), transparent 60%),
    linear-gradient(140deg, #d8642f 0%, #8e2f1c 45%, #2f5f6b 100%);
  background-size: 130% 130%; background-position: 40% 40%;
  -webkit-background-clip: text; background-clip: text; color: transparent; }
.mock-hero-knockout-type .foot { display: flex; justify-content: space-between; align-items: flex-end;
  margin-top: 4cqw; font-size: 1.7cqw; letter-spacing: .08em; text-transform: uppercase; opacity: .72; }
.mock-hero-knockout-type .cta { border: 1px solid #f2efe8; padding: 1.1cqw 2.6cqw; opacity: 1; }
